ALTER TABLE "workspace_currency_change_requests" ADD CONSTRAINT "workspace_currency_change_anchor_check" CHECK (("workspace_currency_change_requests"."original_period_start" IS NULL AND "workspace_currency_change_requests"."billing_anchor_day" IS NULL AND "workspace_currency_change_requests"."next_renewal_at" IS NULL) OR ("workspace_currency_change_requests"."original_period_start" IS NOT NULL AND isfinite("workspace_currency_change_requests"."original_period_start") AND "workspace_currency_change_requests"."original_period_start" < "workspace_currency_change_requests"."effective_at" AND "workspace_currency_change_requests"."billing_anchor_day" IS NOT NULL AND "workspace_currency_change_requests"."billing_anchor_day" BETWEEN 1 AND 31 AND "workspace_currency_change_requests"."next_renewal_at" IS NOT NULL AND isfinite("workspace_currency_change_requests"."next_renewal_at") AND "workspace_currency_change_requests"."next_renewal_at" > "workspace_currency_change_requests"."effective_at"));